#include "ui.h"
#include "drivers/vibrator.h"
#include "drivers/rgb.h"
#include "services/power_manager.h"
#include "ui_helpers.h"
#include "lvgl.h"

#define LED_COLOR_WHITE  (0x00FFFFFFU)

/* The selected color is retained while the light output is switched off. */
static rt_bool_t led_is_on = RT_FALSE;
static uint32_t led_selected_color = LED_COLOR_WHITE;
static uint8_t led_brightness_percent = 100U;

int led_is_enabled(void)
{
    return led_is_on == RT_TRUE;
}

static void led_update_toggle_label(lv_obj_t *label)
{
    if (label != NULL)
        lv_label_set_text(label, led_is_on ? "LIGHT ON" : "LIGHT OFF");
}

static void led_apply_selected_color(void)
{
    uint32_t red;
    uint32_t green;
    uint32_t blue;

    if (led_is_on)
    {
        red = ((led_selected_color >> 16) & 0xFFU) * led_brightness_percent / 100U;
        green = ((led_selected_color >> 8) & 0xFFU) * led_brightness_percent / 100U;
        blue = (led_selected_color & 0xFFU) * led_brightness_percent / 100U;
        rgb_led_set_color((red << 16) | (green << 8) | blue);
    }
}

static void fade_label_exec_cb(void * var, int32_t value)
{
    lv_obj_set_style_opa((lv_obj_t *)var, (lv_opa_t)value, LV_PART_MAIN);
}


	// 这是一个辅助函数，用于在“功德+1”动画播完后，自动删除标签释放内存
static void delete_label_on_clean(lv_anim_t * a) {
    lv_obj_t * label = (lv_obj_t *)a->var;
    lv_obj_del(label);
}

// 这是您在 SLS 中绑定的点击事件函数
void trigger_vibration(lv_event_t * e)
{
    (void)e;

    // 短促的敲击感，避免持续震动
    vibrator_vibrate(90, 60);

    // 3. 同时创建“功德+1”飘字效果
    // 与木鱼图片使用同一父对象，保证定位和绘制层级正确
    lv_obj_t * label = lv_label_create(ui_MainPanel3);
    lv_label_set_text(label, "功德 +1");
    lv_obj_clear_flag(label, LV_OBJ_FLAG_HIDDEN);

    // 使用项目当前启用的 CJK 默认字体，避免硬编码失效的字体符号
    lv_obj_set_style_text_font(label, LV_FONT_DEFAULT, LV_PART_MAIN);
    lv_obj_set_style_text_letter_space(label, 1, LV_PART_MAIN);
    lv_obj_set_style_transform_zoom(label, 150, LV_PART_MAIN);
    lv_obj_set_style_transform_pivot_x(label, 0, LV_PART_MAIN);
    lv_obj_set_style_transform_pivot_y(label, 0, LV_PART_MAIN);

    // 金色主字和偏移阴影，增强立体感
    lv_obj_set_style_text_color(label, lv_color_hex(0xFFD54A), LV_PART_MAIN);
    lv_obj_set_style_text_opa(label, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_shadow_color(label, lv_color_hex(0x4A2500), LV_PART_MAIN);
    lv_obj_set_style_shadow_opa(label, LV_OPA_80, LV_PART_MAIN);
    lv_obj_set_style_shadow_width(label, 4, LV_PART_MAIN);
    lv_obj_set_style_shadow_spread(label, 1, LV_PART_MAIN);
    lv_obj_set_style_shadow_ofs_x(label, 3, LV_PART_MAIN);
    lv_obj_set_style_shadow_ofs_y(label, 4, LV_PART_MAIN);
    
    // 在当前页面顶部固定位置显示，避免嵌套对象坐标导致文字跑出屏幕
    lv_obj_set_width(label, LV_SIZE_CONTENT);
    lv_obj_set_height(label, LV_SIZE_CONTENT);
    lv_obj_align(label, LV_ALIGN_TOP_MID, 0, 45);
    lv_obj_move_foreground(label);

    // 4. 飘字往上移动动画
    lv_anim_t a_y;
    lv_anim_init(&a_y);
    lv_anim_set_var(&a_y, label);
    lv_anim_set_exec_cb(&a_y, (lv_anim_exec_xcb_t)lv_obj_set_y);
    int32_t start_y = lv_obj_get_y_aligned(label);
    lv_anim_set_values(&a_y, start_y, start_y - 55); // 向上漂移 55 像素
    lv_anim_set_time(&a_y, 900);
    lv_anim_start(&a_y);

    // 5. 飘字淡出动画
    lv_anim_t a_fade;
    lv_anim_init(&a_fade);
    lv_anim_set_var(&a_fade, label);
    lv_anim_set_exec_cb(&a_fade, fade_label_exec_cb);
    lv_anim_set_values(&a_fade, LV_OPA_COVER, LV_OPA_TRANSP); // 从不透明到全透明
    lv_anim_set_time(&a_fade, 900);
    lv_anim_set_ready_cb(&a_fade, delete_label_on_clean); // 动画结束时自动销毁 Label
    lv_anim_start(&a_fade);

}

void on_led_toggle(lv_event_t * e)
{
    (void)e;

    if (led_is_on == RT_FALSE)
    {
        led_is_on = RT_TRUE;
        led_apply_selected_color();
        led_update_toggle_label(ui_Label3);
        vibrator_vibrate(65, 60);
    }
    else
    {
        led_is_on = RT_FALSE;
        rgb_led_set_color(0x000000);
        led_update_toggle_label(ui_Label3);
        vibrator_vibrate(65, 60);
    }
}

void on_colorwheel_changed(lv_event_t * e)
{
    lv_obj_t * colorwheel = lv_event_get_target(e);
    lv_color_t color = lv_colorwheel_get_rgb(colorwheel);
    uint32_t rgb = lv_color_to32(color) & 0x00FFFFFFU;

    led_selected_color = rgb;
    led_apply_selected_color();
}

void on_white_color_selected(lv_event_t * e)
{
    (void)e;

    led_selected_color = LED_COLOR_WHITE;
    led_apply_selected_color();
}

void on_rgb_brightness_changed(lv_event_t * e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    lv_obj_t *value_label = lv_event_get_user_data(e);

    led_brightness_percent = (uint8_t)lv_slider_get_value(slider);
    if (value_label != NULL)
        lv_label_set_text_fmt(value_label, "BRIGHTNESS %u%%",
                              (unsigned int)led_brightness_percent);

    led_apply_selected_color();
}

void update_led_toggle_label(lv_obj_t * label)
{
    led_update_toggle_label(label);
}

void on_power_slider_event(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t *slider = lv_event_get_target(e);

    if (event_code != LV_EVENT_RELEASED && event_code != LV_EVENT_PRESS_LOST)
        return;

    if (lv_slider_get_value(slider) >= 95)
    {
        lv_slider_set_value(slider, 100, LV_ANIM_OFF);
        if (power_manager_shutdown() == RT_EOK)
            return;
    }

    lv_slider_set_value(slider, 0, LV_ANIM_ON);
}
